raw = pd.read_csv('raw_responses.csv')
pipeline = pd.read_csv('pipeline_output.csv')

def score_phq9(row):
    items = [f'phq9_{i}' for i in range(1, 10)]
    vals = []
    missing_count = 0
    for it in items:
        v = row[it]
        if pd.isna(v) or v not in [0, 1, 2, 3]:
            missing_count += 1
        else:
            vals.append(v)

    if missing_count >= 2:
        return np.nan, '', np.nan, np.nan
    elif missing_count == 1:
        # scale up: sum(vals) * 9 / 8, rounded, halves round up
        s = sum(vals)
        # Python round(4.5) rounds to 4 (even). We need halves always round up (ceil or decimal Decimal rounding)
        from decimal import Decimal, ROUND_HALF_UP
        raw_val = Decimal(s) * Decimal(9) / Decimal(8)
        total = int(raw_val.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        prorated = True
    else:
        total = sum(vals)
        prorated = False

    # band
    if total <= 4:
        band = 'none-minimal'
    elif total <= 9:
        band = 'mild'
    elif total <= 14:
        band = 'moderate'
    elif total <= 19:
        band = 'moderately severe'
    else:
        band = 'severe'

    # self harm flag
    sh_val = row['phq9_9']
    if pd.isna(sh_val) or sh_val not in [0, 1, 2, 3]:
        sh_flag = np.nan
    else:
        sh_flag = (sh_val > 0)

    return total, band, prorated, sh_flag

