    items = [f'gad7_{i}' for i in range(1, 8)]
    vals = []
    missing_count = 0
    for it in items:
        v = row[it]
        if pd.isna(v) or v not in [0, 1, 2, 3]:
            missing_count += 1
        else:
            vals.append(v)

    if missing_count >= 2:
        return np.nan, '', np.nan
    elif missing_count == 1:
        from decimal import Decimal, ROUND_HALF_UP
        s = sum(vals)
        raw_val = Decimal(s) * Decimal(7) / Decimal(6)
        total = int(raw_val.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        prorated = True
    else:
        total = sum(vals)
        prorated = False

    if total <= 4:
        band = 'minimal'
    elif total <= 9:
        band = 'mild'
    elif total <= 14:
        band = 'moderate'
    else:
        band = 'severe'

    return total, band, prorated

def score_rses(row):
    items = [f'rses_{i}' for i in range(1, 11)]
    rev_items = {3, 5, 8, 9, 10}
    vals = []
    missing_count = 0
